package edu.campusconnect.model;
import jakarta.persistence.*;import java.io.*;import java.util.*;
@Entity @Table(name="student_skills") @IdClass(StudentSkill.Key.class) public class StudentSkill {@Id @ManyToOne @JoinColumn(name="student_id") public Student student; @Id @ManyToOne @JoinColumn(name="skill_id") public Skill skill; @Enumerated(EnumType.STRING) public Level proficiency; protected StudentSkill(){} public StudentSkill(Student s,Skill k,Level l){student=s;skill=k;proficiency=l;} public static class Key implements Serializable {public UUID student;public Long skill;public Key(){} public boolean equals(Object o){return o instanceof Key k && Objects.equals(student,k.student)&&Objects.equals(skill,k.skill);} public int hashCode(){return Objects.hash(student,skill);}} public enum Level {BEGINNER,INTERMEDIATE,ADVANCED}}
